import React, { useState, useMemo, useRef, useEffect, useCallback } from 'react';
import { ChevronDownIcon, ChevronLeftIcon, ChevronRightIcon, XCircleIcon } from '@heroicons/react/24/solid';

const useOutsideAlerter = (ref, callback) => {
  useEffect(() => {
    function handleClickOutside(event) {
      if (ref.current && !ref.current.contains(event.target)) {
        callback();
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, [ref, callback]);
};

const CalendarGrid = ({ currentDate, availableDatesMap, selectedThrows, clickedDate, onDateClick, onDateHover, onMonthChange }) => {
  const generateCalendarGrid = () => {
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const firstDayOfMonth = new Date(year, month, 1).getDay();
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const grid = [];
    for (let i = 0; i < firstDayOfMonth; i++) grid.push({ key: `pad-${i}`, isEmpty: true });
    for (let day = 1; day <= daysInMonth; day++) {
      const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
      grid.push({ key: dateStr, day, dateStr, hasData: availableDatesMap.has(dateStr) });
    }
    return grid;
  };

  return (
    <div className="w-72">
      <div className="flex justify-between items-center mb-4">
        <button onClick={() => onMonthChange(-1)} className="p-2 rounded-full hover:bg-gray-100 text-gray-600"><ChevronLeftIcon className="h-5 w-5"/></button>
        <div className="font-bold text-lg text-gray-800">{currentDate.toLocaleString('default', { month: 'long' })} {currentDate.getFullYear()}</div>
        <button onClick={() => onMonthChange(1)} className="p-2 rounded-full hover:bg-gray-100 text-gray-600"><ChevronRightIcon className="h-5 w-5"/></button>
      </div>
      <div className="grid grid-cols-7 text-center text-sm text-gray-500 font-medium">
        {['S', 'M', 'T', 'W', 'T', 'F', 'S'].map((day, index) => (
          <div key={`${day}-${index}`} className="py-2">{day}</div>
        ))}
      </div>
      <div className="grid grid-cols-7 text-center" onMouseLeave={() => onDateHover(null, false)}>
        {generateCalendarGrid().map(dayInfo => {
          if (dayInfo.isEmpty) return <div key={dayInfo.key}></div>;
          const { hasData, day, dateStr } = dayInfo;
          const isSelectedOnCalendar = selectedThrows[dateStr]?.length > 0;
          const isClickedForDisplay = clickedDate === dateStr;

          const dayClasses = `w-9 h-9 flex items-center justify-center rounded-full relative text-sm transition-colors duration-150 font-medium ${
            isClickedForDisplay ? 'bg-blue-500 text-white font-bold' : 
            isSelectedOnCalendar ? 'bg-green-400 text-white' :
            hasData ? 'bg-green-200 text-green-900 cursor-pointer hover:bg-green-300' : 
            'bg-gray-100 text-gray-400 cursor-not-allowed'
          }`;
          return (
            <div 
              key={dayInfo.key} 
              className="py-1 flex items-center justify-center"
              onMouseEnter={() => onDateHover(dateStr, hasData)}
              onClick={() => onDateClick(dateStr, hasData)}
            >
              <div className={dayClasses}>{day}</div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

const ThrowsList = ({ date, throws, selectedThrows, onThrowChange }) => {
    return (
        <div className="w-56 border-l border-gray-200 pl-4">
            <div className="font-bold text-md text-gray-800 mb-4">{date}</div>
            <div className="max-h-60 overflow-y-auto pr-2">
                {throws === null ? (
                    <p className="text-sm text-gray-500">Loading...</p>
                ) : throws.length > 0 ? (
                    throws.map((throwData, index) => {
                        const isChecked = selectedThrows[date]?.includes(index);
                        return (
                            <label key={index} className="flex items-center p-2 rounded-md hover:bg-gray-100 cursor-pointer">
                                <input 
                                    type="checkbox" 
                                    className="h-4 w-4 accent-blue-500 rounded mr-3 flex-shrink-0"
                                    checked={!!isChecked}
                                    onChange={() => onThrowChange(date, index)}
                                />
                                <div className="flex items-baseline whitespace-nowrap">
                                    <span className="text-sm mr-1.5">{`Throw ${index + 1}`}</span>
                                    <span className="text-gray-500 text-xs mr-2">({throwData.time})</span>
                                    <span className="font-semibold text-gray-700 text-xs bg-gray-200 px-1.5 py-0.5 rounded">
                                        {throwData.playerStats.range}m
                                    </span>
                                </div>
                            </label>
                        );
                    })
                ) : (
                    <p className="text-sm text-gray-500">No throws recorded.</p>
                )}
            </div>
        </div>
    );
};

const CalendarFilter = ({ 
  availableDates = [], 
  selectedThrows = {}, 
  onChange = () => {}, 
  onReset = () => {} 
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const [clickedDate, setClickedDate] = useState(null);
  const [hoveredDate, setHoveredDate] = useState(null);
  const [isHoveringDateWithData, setIsHoveringDateWithData] = useState(false);
  const [throwsDataCache, setThrowsDataCache] = useState({});
  const [currentDate, setCurrentDate] = useState(new Date());
  const wrapperRef = useRef(null);

  const closeDropdown = () => {
    setIsOpen(false);
    setHoveredDate(null);
  };
  useOutsideAlerter(wrapperRef, closeDropdown);

  const availableDatesMap = useMemo(() => {
    const map = new Map();
    availableDates.forEach(d => map.set(d.value, d.throwCount));
    return map;
  }, [availableDates]);

  const getThrowsForDate = useCallback((dateStr) => {
    if (!dateStr || !availableDatesMap.has(dateStr) || throwsDataCache[dateStr]) return;
    
    setThrowsDataCache(prev => ({ ...prev, [dateStr]: null }));
    
    import('../../services/api').then(api => {
        api.fetchJavelinDataByDate(dateStr).then(data => {
            setThrowsDataCache(prev => ({ ...prev, [dateStr]: data.throws }));
        });
    });
  }, [throwsDataCache, availableDatesMap]);

  const handleDateHover = (dateStr, hasData) => {
    setHoveredDate(dateStr);
    setIsHoveringDateWithData(hasData);
    if (hasData) {
      getThrowsForDate(dateStr);
    }
  };

  const handleDateClick = (dateStr, hasData) => {
    if (!hasData) return;
    if (clickedDate === dateStr) {
      setClickedDate(null);
    } else {
      setClickedDate(dateStr);
      getThrowsForDate(dateStr);
    }
  };
  
  const handleThrowCheckboxChange = (dateStr, throwIndex) => {
    const newSelection = JSON.parse(JSON.stringify(selectedThrows));
    const dateSelections = newSelection[dateStr] || [];
    
    if (dateSelections.includes(throwIndex)) {
      newSelection[dateStr] = dateSelections.filter(i => i !== throwIndex);
      if (newSelection[dateStr].length === 0) {
        delete newSelection[dateStr];
      }
    } else {
      newSelection[dateStr] = [...dateSelections, throwIndex].sort((a, b) => a - b);
    }
    onChange(newSelection);
  };

  const handleReset = () => {
    onReset();
    setClickedDate(null);
  };
  
  const totalSelectedCount = Object.values(selectedThrows).reduce((acc, throws) => acc + throws.length, 0);
  const selectionText = totalSelectedCount === 0 ? "Select throws..." : `${totalSelectedCount} throw(s) selected`;

  const changeMonth = (amount) => {
    setCurrentDate(prev => {
      const newDate = new Date(prev);
      newDate.setMonth(newDate.getMonth() + amount);
      return newDate;
    });
  };
  
  const displayDate = isHoveringDateWithData ? hoveredDate : clickedDate;
  const throwsForDisplay = displayDate ? throwsDataCache[displayDate] : null;
  const shouldShowThrowsList = !!displayDate;
  const shouldShowPlaceholder = !isHoveringDateWithData && !clickedDate;

  return (
    <div className="flex items-end space-x-2">
      <div className="relative w-full" ref={wrapperRef}>
        <label className="block text-sm font-medium text-gray-700 mb-2">
          Select throws to compare:
        </label>
        <button onClick={() => setIsOpen(!isOpen)} className="bg-white border border-gray-300 rounded-md shadow-sm pl-3 pr-10 py-2 text-left w-full flex justify-between items-center">
          <span className="text-sm">{selectionText}</span>
          <ChevronDownIcon className={`h-5 w-5 text-gray-400 transition-transform ${isOpen ? 'transform rotate-180' : ''}`} />
        </button>
        {isOpen && (
          <div className="absolute mt-1 bg-white text-gray-900 border border-gray-200 rounded-lg shadow-2xl z-20 p-4 inline-flex">
            <CalendarGrid
              currentDate={currentDate}
              availableDatesMap={availableDatesMap}
              selectedThrows={selectedThrows}
              clickedDate={clickedDate}
              onDateClick={handleDateClick}
              onDateHover={handleDateHover}
              onMonthChange={changeMonth}
            />
            
            <div className="w-56">
                {shouldShowThrowsList && (
                    <ThrowsList
                        date={displayDate}
                        throws={throwsForDisplay}
                        selectedThrows={selectedThrows}
                        onThrowChange={handleThrowCheckboxChange}
                    />
                )}
                {shouldShowPlaceholder && (
                    <div className="h-full flex items-center justify-center">
                        <p className="text-xs text-gray-400 text-center px-4">Hover or click a date to see throws.</p>
                    </div>
                )}
            </div>
          </div>
        )}
      </div>
      <button
        onClick={handleReset}
        disabled={totalSelectedCount === 0}
        className="px-3 py-2 bg-red-500 text-white rounded-md shadow-sm transition-all duration-200 hover:bg-red-600 disabled:opacity-40 disabled:cursor-not-allowed"
        aria-label="Reset selections"
      >
        <XCircleIcon className="h-5 w-5" />
      </button>
    </div>
  );
};

export default CalendarFilter;
